views.css:
/* Cards rules retained from the original Steward component cascade. */
.ogui-theme .native-answer-title{font:600 14px/1.5 var(--font-ui);margin:0 0 5px;overflow-wrap:anywhere;color:var(--foreground)}
.ogui-theme button.answer-icon-button{font:14px/1.6 var(--font-ui);display:inline-flex;align-items:center;justify-content:center;flex:none;width:32px;height:32px;min-height:32px;margin:0;padding:7px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--muted-foreground);cursor:pointer;box-shadow:none;transform:none}
.ogui-theme button.answer-icon-button:hover{background:var(--hover);color:var(--foreground)}
.ogui-theme button.answer-icon-button:disabled{opacity:.4;cursor:default}
.ogui-theme button.answer-icon-button svg{width:16px;height:16px;flex:none}
.ogui-theme .native-carousel{position:relative;min-width:0}
.ogui-theme .native-carousel-controls{display:flex;align-items:center;justify-content:flex-end;gap:4px;margin:0 36px 12px 0;min-height:32px;font-size:12px;color:var(--muted-foreground)}
.ogui-theme .native-carousel-list{position:relative;display:grid;grid-auto-flow:column;grid-auto-columns:minmax(240px,calc(50% - 8px));gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;overscroll-behavior-x:contain;padding:2px 0 6px}
.ogui-theme .native-carousel-list::-webkit-scrollbar{display:none}
.ogui-theme .native-result-card{display:flex;flex-direction:column;gap:10px;min-width:0;scroll-snap-align:start;padding:16px;border:1px solid var(--border);border-radius:12px;background:var(--card);transition:border-color .15s}
.ogui-theme .native-result-card:hover{border-color:var(--control-border)}
.ogui-theme .native-result-card[data-selected=true]{border-color:var(--foreground);background:var(--card)}
.ogui-theme .native-result-card img{width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:7px}
.ogui-theme button.native-card-title{padding:0;margin:0;border:0;border-radius:0;background:transparent;color:var(--foreground);font:600 14px/1.5 var(--font-ui);text-align:start;cursor:pointer;justify-content:flex-start;align-self:flex-start;min-height:24px;line-height:1.5}
.ogui-theme button.native-card-title:hover{background:transparent;color:var(--foreground);text-decoration:underline;text-underline-offset:3px}
.ogui-theme .native-result-card p{margin:0;font-size:13px;color:var(--muted-foreground);line-height:1.6}
.ogui-theme .native-result-card a{align-self:flex-start;margin-top:auto;font-size:13px;text-underline-offset:3px}
.ogui-theme .native-carousel-heading{display:flex;align-items:center;gap:12px;min-width:0;min-height:32px;padding-inline-end:42px;margin-bottom:10px}
.ogui-theme .native-carousel .native-carousel-heading>.native-answer-title{flex:1;min-width:0;margin:0;padding:0}
.ogui-theme .native-carousel-heading .native-carousel-controls{flex:none;margin:0;min-height:32px;margin-inline-start:auto}
html.ogui-theme[data-host-compact] .answer-icon-button{width:44px;height:44px;min-height:44px}
html.ogui-theme[data-host-compact] .native-carousel-list{grid-auto-columns:minmax(220px,88%)}
html.ogui-theme[data-host-compact] .native-result-card a{display:inline-flex;align-items:center;min-height:44px}
html.ogui-theme[data-host-compact] .native-carousel-heading{min-height:44px;padding-inline-end:54px}
html.ogui-theme[data-host-compact] .native-carousel-heading .native-carousel-controls{min-height:44px}

