// Private Cards implementation, executed only in an opaque-origin frame.
// The parent binds every message to the original component; no refs, HTTP,
// credentials, tool calls or ordinary-input proposals are accepted here.
(()=>{
  const start=()=>{
    const root=document.querySelector('.native-carousel');
    if(!root)return;
    const list=root.querySelector('.native-carousel-list');
    const cards=[...list.children];
    const controls=root.querySelector('.native-carousel-controls');
    const [previous,next]=controls.querySelectorAll('button');
    const counter=controls.querySelector('span');
    let index=0,restored=false;
    const post=value=>parent.postMessage({channel:'steward-cards-view',...value},'*');
    const paint=()=>{previous.disabled=!restored||index===0;next.disabled=!restored||index===cards.length-1;counter.textContent=`${index+1} / ${cards.length}`};
    const save=id=>post({type:'view-state',state:{index},...(id?{id}:{})});
    // A last card cannot always align its left edge with the viewport. Use
    // the browser's reachable scroll positions, including during restoration.
    const position=item=>Math.max(0,Math.min(cards[item].offsetLeft-list.offsetLeft,list.scrollWidth-list.clientWidth));
    const move=(value,behavior)=>{
      const changed=index!==value;index=value;paint();
      list.scrollTo({left:position(index),behavior});
      if(changed)save();
    };
    // Expanding a surface or changing viewport width must keep the same
    // visible item without manufacturing a new user-state mutation.
    new ResizeObserver(()=>{if(restored)list.scrollTo({left:position(index),behavior:'instant'})}).observe(list);
    previous.addEventListener('click',()=>{if(restored)move(Math.max(0,index-1),'smooth')});
    next.addEventListener('click',()=>{if(restored)move(Math.min(cards.length-1,index+1),'smooth')});
    list.addEventListener('scroll',()=>{
      if(!restored)return;
      const distance=item=>Math.abs(position(item)-list.scrollLeft);
      const nearest=cards.reduce((best,node,i)=>distance(i)<distance(best)?i:best,index);
      if(index!==nearest){index=nearest;paint();save()}
    });
    cards.forEach((card,item)=>{
      card.querySelector('.native-card-title').addEventListener('click',()=>{if(restored)post({type:'select',item})});
    });
    const imageSlots=new Map();
    cards.forEach((card,item)=>{const image=card.querySelector('img[data-card-image]');if(image)imageSlots.set(image,item)});
    const images=new IntersectionObserver(entries=>{
      for(const entry of entries){if(entry.isIntersecting){post({type:'image-request',item:imageSlots.get(entry.target)});images.unobserve(entry.target)}}
    },{root:list,rootMargin:'0px 240px'});
    const group=selected=>cards.forEach(card=>{
      const active=card.querySelector('.native-card-title').textContent===selected;
      card.dataset.selected=String(active);card.querySelector('.native-card-title').setAttribute('aria-pressed',String(active));
    });
    addEventListener('message',event=>{
      const value=event.data;
      if(event.source!==parent||value?.channel!=='steward-cards-view')return;
      if(value.type==='restore'&&!restored){
        const saved=value.state?.index;
        index=Number.isSafeInteger(saved)?Math.max(0,Math.min(cards.length-1,saved)):0;
        restored=true;group(typeof value.selected==='string'?value.selected:'');paint();
        list.scrollTo({left:position(index),behavior:'instant'});
        post({type:'restored'});
        for(const image of imageSlots.keys())images.observe(image);
      }
      if(value.type==='image'&&Number.isInteger(value.item)&&value.image instanceof Blob&&['image/png','image/jpeg','image/webp','image/gif'].includes(value.image.type)){
        const image=cards[value.item]?.querySelector('img[data-card-image]');
        if(image){const source=URL.createObjectURL(value.image),release=()=>URL.revokeObjectURL(source);image.addEventListener('load',release,{once:true});image.addEventListener('error',release,{once:true});// The package observer already selected this image for prefetch. Native
        // lazy loading can otherwise leave a granted Blob undecoded in an
        // older, restored message outside the current page viewport.
        image.loading='eager';image.src=source}
      }
      if(value.type==='image-error'&&Number.isInteger(value.item)){const image=cards[value.item]?.querySelector('img[data-card-image]');if(image)image.dataset.imageUnavailable='true'}
      if(value.type==='group'&&typeof value.selected==='string'&&value.selected.length<=300)group(value.selected);
      if(value.type==='capture'&&restored&&typeof value.id==='string'&&value.id.length<=64)save(value.id);
    });
    paint();post({type:'ready'});
  };
  if(document.readyState==='loading')addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
